#!/usr/bin/env node

import { createHash } from "node:crypto";
import { copyFile, mkdir, readFile, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

import tailwindcss from "@tailwindcss/postcss";
import postcss from "postcss";

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputRoot = path.join(repositoryRoot, "public/static/article-styles");
const manifestPath = path.join(repositoryRoot, "lib/generated/article-style-assets.ts");
const checkOnly = process.argv.includes("--check");

const digest = (value) => createHash("sha256").update(value).digest("hex").slice(0, 12);
const prismSourcePath = path.join(repositoryRoot, "css/prism.css");
const katexRoot = path.join(repositoryRoot, "node_modules/katex/dist");
const katexSourcePath = path.join(katexRoot, "katex.min.css");
const katexFontRoot = path.join(katexRoot, "fonts");

const prismSource = await readFile(prismSourcePath, "utf8");
const prismResult = await postcss([tailwindcss()]).process(prismSource, {
  from: prismSourcePath,
  map: false,
});
const prismCss = prismResult.css;
const prismHash = digest(prismCss);
const prismFileName = `prism.${prismHash}.css`;
const promoterSource = `(()=>{const e=()=>{const e=document.querySelector('link[data-article-style="katex"]');e&&(e.media="all")};"complete"===document.readyState?e():addEventListener("load",e,{once:!0})})();`;
const promoterHash = digest(promoterSource);
const promoterFileName = `promote.${promoterHash}.js`;

const katexSource = await readFile(katexSourcePath, "utf8");
const fontNames = [...katexSource.matchAll(/url\(fonts\/([^)]*?\.woff2)\)/g)]
  .map((match) => match[1])
  .filter((fontName, index, names) => names.indexOf(fontName) === index)
  .toSorted();
const fontEntries = await Promise.all(
  fontNames.map(async (fontName) => ({
    fontName,
    contents: await readFile(path.join(katexFontRoot, fontName)),
  }))
);
const fontHash = digest(
  Buffer.concat(
    fontEntries.flatMap(({ fontName, contents }) => [Buffer.from(`${fontName}\0`), contents])
  )
);
const fontDirectoryName = `fonts.${fontHash}`;
const katexCss = katexSource
  .replace(
    /src:url\(fonts\/([^)]*?\.woff2)\) format\("woff2"\),url\(fonts\/[^)]*?\.woff\) format\("woff"\),url\(fonts\/[^)]*?\.ttf\) format\("truetype"\)/g,
    `src:url(${fontDirectoryName}/$1) format("woff2")`
  )
  .replace("/*# sourceMappingURL=katex.min.css.map*/", "");
const katexHash = digest(katexCss);
const katexFileName = `katex.${katexHash}.css`;
const manifest =
  `// Generated by scripts/generate-article-style-assets.mjs.\n` +
  `// The content hashes make the long-lived /static cache policy safe.\n` +
  `export const articleStyleAssets = {\n` +
  `  prism: "/static/article-styles/${prismFileName}",\n` +
  `  katex: "/static/article-styles/${katexFileName}",\n` +
  `  promoter: "/static/article-styles/${promoterFileName}",\n` +
  `} as const;\n`;

const expectedFiles = [
  { path: path.join(outputRoot, prismFileName), contents: prismCss },
  { path: path.join(outputRoot, katexFileName), contents: katexCss },
  { path: path.join(outputRoot, promoterFileName), contents: promoterSource },
  { path: manifestPath, contents: manifest },
];

if (checkOnly) {
  const mismatches = [];
  for (const expected of expectedFiles) {
    const actual = await readFile(expected.path, "utf8").catch(() => null);
    if (actual !== expected.contents) mismatches.push(path.relative(repositoryRoot, expected.path));
  }
  for (const { fontName, contents } of fontEntries) {
    const outputPath = path.join(outputRoot, fontDirectoryName, fontName);
    const output = await readFile(outputPath).catch(() => null);
    if (!output?.equals(contents)) mismatches.push(path.relative(repositoryRoot, outputPath));
  }
  if (mismatches.length > 0) {
    console.error(`Article style assets are missing or stale:\n${mismatches.join("\n")}`);
    process.exitCode = 1;
  } else {
    console.log(`Article style assets verified (${fontEntries.length} WOFF2 fonts).`);
  }
} else {
  await mkdir(outputRoot, { recursive: true });
  await mkdir(path.dirname(manifestPath), { recursive: true });
  await mkdir(path.join(outputRoot, fontDirectoryName), { recursive: true });
  for (const expected of expectedFiles) {
    await writeFile(expected.path, expected.contents);
  }
  for (const { fontName } of fontEntries) {
    await copyFile(
      path.join(katexFontRoot, fontName),
      path.join(outputRoot, fontDirectoryName, fontName)
    );
  }
  const prismBytes = (await stat(path.join(outputRoot, prismFileName))).size;
  const katexBytes = (await stat(path.join(outputRoot, katexFileName))).size;
  const promoterBytes = (await stat(path.join(outputRoot, promoterFileName))).size;
  const fontBytes = fontEntries.reduce((total, entry) => total + entry.contents.length, 0);
  console.log(
    `Generated ${prismFileName} (${prismBytes} B), ${katexFileName} (${katexBytes} B), ${promoterFileName} (${promoterBytes} B), and ${fontEntries.length} WOFF2 fonts (${fontBytes} B).`
  );
}
